import type { WebModuleDefinition } from '@veqsio/sdk'
import { generatedModules } from './module-registry.generated'

/** Web entries of the modules bundled into this build (generated by scripts/gen-module-registry.ts). */
export const bundledWebModules: WebModuleDefinition[] = generatedModules

export function findWebModule(id: string): WebModuleDefinition | undefined {
  return bundledWebModules.find((m) => m.id === id)
}

export interface ActiveModuleWeb {
  id: string
  name: string
  feature: string | null
  web: {
    navItems: Array<{ key: string; title: string; path: string; hidden?: boolean }>
    adminPages: Array<{ key: string; title: string; path: string; description?: string }>
    issuePanels?: Array<{ key: string; title: string; location: 'sidebar' | 'content' }>
  }
}

/** Resolves /m/<id>/<path...> to the page key declared in the manifest. */
export function resolveModulePage(mod: ActiveModuleWeb, segments: string[]): { kind: 'pages' | 'adminPages'; key: string } | null {
  const path = segments.join('/')
  const nav = mod.web.navItems.find((n) => n.path === path)
  if (nav) return { kind: 'pages', key: nav.key }
  const admin = mod.web.adminPages.find((n) => n.path === path)
  if (admin) return { kind: 'adminPages', key: admin.key }
  return null
}

export { issuePanelsFor, type IssuePanelRef } from './module-panels'
